<template><el-dialog v-model="visible" title="上传文档与断点续传" width="880px" :close-on-click-modal="!busy" :before-close="beforeClose"><el-alert v-if="error" :title="error" type="error" :closable="false" class="ps-section"/><el-form label-width="100px"><el-form-item label="所属空间" required><el-select v-model="spaceId" :disabled="busy"><el-option v-for="s in spaces" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-button :disabled="busy" @click="personal">建立个人空间</el-button></el-form-item><el-form-item label="可见范围"><el-select v-model="visibility" :disabled="busy||spaces.find(s=>String(s.id)===String(spaceId))?.type==='PERSONAL'"><el-option label="仅本人" value="PRIVATE"/><el-option label="所属空间" value="ORGANIZATION"/><el-option label="组织公开" value="PUBLIC"/></el-select></el-form-item><el-form-item label="选择文件" required><div class="file-picker"><input type="file" aria-label="选择需要上传的文档" :accept="accept" :disabled="busy" @change="chooseFile"/><p v-if="uploadSizeLimit" class="ps-muted">当前空间单文件上限 {{(uploadSizeLimit/1024/1024).toFixed(2)}} MiB</p><p v-if="file" class="ps-muted">{{file.name}} · {{(file.size/1024/1024).toFixed(2)}} MB</p></div></el-form-item><el-form-item label="续传记录"><el-input v-model="resumeId" placeholder="选填上传记录 ID；需重新选择原文件" :disabled="busy"/></el-form-item></el-form><el-card class="ps-section" shadow="never"><template #header>我的上传记录</template><el-alert v-if="uploadsError" :title="uploadsError" type="error" :closable="false"/><el-form inline><el-form-item label="上传状态"><el-select v-model="uploadQuery.state"><el-option label="未完成" value="UPLOADING"/><el-option label="已合并" value="MERGED"/><el-option label="已过期" value="EXPIRED"/></el-select></el-form-item><el-form-item label="文件名"><el-input v-model="uploadQuery.keyword" clearable/></el-form-item><el-button :disabled="busy" @click="loadUploads(true)">查询续传记录</el-button><el-button :disabled="busy" @click="newUpload">新文件上传</el-button></el-form><el-table :data="uploads" v-loading="uploadsLoading"><el-table-column prop="filename" label="原记录文件名" min-width="180"/><el-table-column label="空间" min-width="150"><template #default="{row}">{{spaces.find(s=>String(s.id)===String(row.spaceId))?.name||row.spaceId||'个人根目录'}}</template></el-table-column><el-table-column prop="visibility" label="可见范围" width="150"/><el-table-column prop="createdAt" label="创建时间" min-width="180"/><el-table-column label="分片" width="100"><template #default="{row}">{{row.completedChunks.length}} / {{row.totalChunks}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link :disabled="busy||row.state==='EXPIRED'" @click="selectUpload(row)">{{row.state==='MERGED'?'读取文档':row.state==='EXPIRED'?'请重新上传':'选择续传'}}</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="uploadQuery.pageNum" :page-size="uploadQuery.pageSize" :total="uploadsTotal" layout="total,prev,pager,next" @current-change="loadUploads()"/></el-card><el-progress :percentage="progress"/><p role="status">{{phase}}</p><p v-if="manifest">原记录文件名：{{manifest.filename}} · 上传 ID：{{manifest.uploadId}} · 已完成 {{manifest.completedChunks.length}} 个分片 <span v-if="manifest.estimatedTokens!==undefined">· 预计用量 {{manifest.estimatedTokens}}</span></p><el-alert v-if="result" :title="`已合并为文档「${result.title}」，状态：${stateLabel(result.state)}`" type="success" :closable="false"/><template #footer><el-button v-if="busy" @click="pause">暂停上传</el-button><el-button @click="visible=false" :disabled="busy">关闭</el-button><el-button v-hasPermi="['paismart:document:upload']" type="primary" :loading="busy" :disabled="!file || !spaceId || !!fileError" @click="start">{{resumeId||manifest?'继续上传':'开始上传'}}</el-button></template></el-dialog></template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import {listUploads,supportedUploadTypes,mergeUpload} from '@/api/paismart/upload'
import { createPersonalSpace } from '@/api/paismart/spaces'
import type { Id, Space,Upload } from '@/types/paismart'
import { useChunkUpload } from '../../composables/useChunkUpload'
import { errorText,stateLabel,usePage } from '../../composables/usePage'
const props=defineProps<{modelValue:boolean;spaces:Space[];initialSpace?:Id}>(),emit=defineEmits<{ 'update:modelValue':[boolean]; uploaded:[]; spacesChanged:[] }>()
const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)}),file=ref<File>(),spaceId=ref<Id>(),visibility=ref('PRIVATE'),resumeId=ref('')
const {manifest,busy,progress,phase,error,result,run,pause,reset}=useChunkUpload()
const {rows:uploads,total:uploadsTotal,query:uploadQuery,loading:uploadsLoading,error:uploadsError,load:loadUploads}=usePage(listUploads,{state:'UPLOADING'}),extensions=ref<string[]>([]),accept=computed(()=>extensions.value.map(ext=>'.'+ext).join(',')),selectedUpload=ref<Upload>(),fileError=ref('')
const uploadSizeLimit=computed(()=>{const space=props.spaces.find(s=>String(s.id)===String(spaceId.value));return space?.canManage!==true?space?.uploadMaxSizeBytes:undefined})
function validateFile(){fileError.value='';if(!file.value)return;const ext=file.value.name.split('.').pop()?.toLowerCase();if(extensions.value.length&&!extensions.value.includes(ext??''))fileError.value='当前文件格式不受支持';else if(uploadSizeLimit.value&&file.value.size>uploadSizeLimit.value)fileError.value='文件超出当前空间单文件大小上限';if(fileError.value)error.value=fileError.value}
function newUpload(){reset();resumeId.value='';selectedUpload.value=undefined;fileError.value=''}
async function selectUpload(row:Upload){newUpload();if(row.state==='MERGED'){try{manifest.value=row;result.value=(await mergeUpload(row.uploadId,crypto.randomUUID())).data;progress.value=100;phase.value='原上传已合并，已读取原文档';emit('uploaded')}catch(e){error.value=errorText(e)}return};selectedUpload.value=row;resumeId.value=String(row.uploadId);spaceId.value=row.spaceId;visibility.value=row.visibility??'PRIVATE';file.value=undefined;phase.value='请重新选择原文件，摘要与大小将由客户端和服务端核对'}
function chooseFile(event:Event){const next=(event.target as HTMLInputElement).files?.[0];if(!selectedUpload.value&&file.value&&next&&(next.name!==file.value.name||next.size!==file.value.size||next.lastModified!==file.value.lastModified))newUpload();if(result.value)newUpload();file.value=next;validateFile()}
async function start(){if(!file.value||!spaceId.value)return;validateFile();if(fileError.value)return;await run(file.value,spaceId.value,visibility.value,resumeId.value||undefined);if(manifest.value)resumeId.value=String(manifest.value.uploadId);if(result.value){emit('uploaded');selectedUpload.value=undefined;await loadUploads()}}
function beforeClose(done:()=>void){if(!busy.value)done()}
async function personal(){try{const space=(await createPersonalSpace()).data;spaceId.value=space.id;visibility.value='PRIVATE';emit('spacesChanged')}catch(e){error.value=e instanceof Error?e.message:'个人空间未能建立'}}
watch(()=>spaceId.value,id=>{if(props.spaces.find(s=>String(s.id)===String(id))?.type==='PERSONAL')visibility.value='PRIVATE';validateFile()})
watch(()=>props.modelValue,async v=>{if(!v)return;if(!spaceId.value)spaceId.value=props.initialSpace??props.spaces[0]?.id;void loadUploads();try{extensions.value=(await supportedUploadTypes()).data.map(row=>row.extension.replace(/^\./,''));validateFile()}catch(e){error.value=errorText(e)}})
onBeforeUnmount(pause)
</script>

<style scoped>.file-picker{width:100%}.file-picker p{margin:8px 0}.el-form--inline :deep(.el-select){width:150px}</style>
